import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { lateOf } from '../overdue/overdue';
import { dueTotal, personSplit, useRates } from './rates';
import { useFigure } from '../locale/locale';
import { useShared } from './due.slot';

// A person's settled-total and open-total (their due-total before the cap, split by status), and the
// sheet's: everyone's added up, not trimmed.
function SplitHead() {
  return (
    <>
      <th>Settled total</th>
      <th>Open total</th>
    </>
  );
}

export function useSplit() {
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const shared = useShared(sheet);
  return (person: Person) =>
    personSplit(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]),
      rates.data,
      person.grades,
      today,
      floorOf(settings),
      lateOf(settings, today, [person]),
      shared(person),
    );
}

function PersonSplit({ person }: { person: Person }) {
  const fig = useFigure();
  const { settled, open } = useSplit()(person);
  return (
    <>
      <td data-testid="person-settled-total">{fig(settled)}</td>
      <td data-testid="person-open-total">{fig(open)}</td>
    </>
  );
}

function SplitTotal() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useSplit());
  return (
    <p>
      Settled total <strong data-testid="rollup-settled-total">{fig(dueTotal(figures.map((f) => f.settled)))}</strong>{' '}
      Open total <strong data-testid="rollup-open-total">{fig(dueTotal(figures.map((f) => f.open)))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 15.2, Component: SplitHead }),
  PersonColumns.fill({ order: 15.2, Component: PersonSplit }),
  HomeMain.fill({ order: 35.5, Component: SplitTotal }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet } from '../../session/session';
import { type Person, usePeople } from '../people/people';
import { dueTotal } from '../rates/rates';
import { cutTotal, usePools } from './pools';
import { useFigure } from '../locale/locale';

// A person's cut total (see `cutTotal`) and the sheet's cut total (everyone's added up).

function CutHead() {
  return <th>Cut total</th>;
}

function PersonCut({ person }: { person: Person }) {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const pools = usePools(sheet);
  return <td data-testid="person-cut-total">{fig(cutTotal(pools.data ?? [], person.id))}</td>;
}

function CutTotal() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const pools = usePools(sheet);
  return (
    <p>
      Cut total{' '}
      <strong data-testid="rollup-cut-total">{fig(dueTotal((people.data ?? []).map((p) => cutTotal(pools.data ?? [], p.id))))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 19.96, Component: CutHead }),
  PersonColumns.fill({ order: 19.96, Component: PersonCut }),
  HomeMain.fill({ order: 30.5, Component: CutTotal }),
];
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet } from '../../session/session';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { STATUSES, statusCount, useClaims } from '../claims/claims';
import { useDescendants, useSheetToday } from '../sheet/sheet';
import { dueTotal, trimmedTotal } from '../rates/rates';
import { usePersonDue } from '../rates/due.slot';
import { useOverdue } from '../overdue/overdue.slot';
import { useFigure } from '../locale/locale';
import { useGradeCodes } from '../grades/grades';

type Figures = {
  people: string[][];
  due: string[];
  overdue: string[];
  gradeDue: Record<string, string[]>;
  statuses: Record<string, number>;
};

const noFigures = (): Figures => ({
  people: [],
  due: [],
  overdue: [],
  gradeDue: Object.fromEntries(GRADES.map((g) => [g, [] as string[]])),
  statuses: Object.fromEntries(STATUSES.map((s) => [s, 0])),
});

/** Names are compared ignoring case and the spaces around them. */
const nameKey = (name: string) => name.trim().toLowerCase();

/** How many people there are across the tree, given each one's name and aliases (as names are compared): people
 *  whose names or aliases match, directly or through others, are one person. */
function distinctPeople(names: string[][]): number {
  const parent = names.map((_, i) => i);
  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
  const owner = new Map<string, number>();
  names.forEach((keys, i) =>
    keys.filter((k) => k !== '').forEach((k) => {
      const j = owner.get(k);
      if (j === undefined) owner.set(k, i);
      else parent[root(i)] = root(j);
    }),
  );
  return names.filter((_, i) => root(i) === i).length;
}

/** Adds the first sheet's figures (as that sheet shows them) to those so far, then the rest's, one sheet per
 *  component so each reads its sheet with the same hooks; shows the sums once every sheet is added. */
function Consolidate({ sheets, sofar }: { sheets: string[]; sofar: Figures }) {
  const fig = useFigure();
  const [first, ...rest] = sheets;
  const people = usePeople(first);
  const overdueOf = useOverdue(first);
  const claims = useClaims(first);
  const today = useSheetToday(first);
  const personDue = usePersonDue(first);
  const grades = useGradeCodes(first);
  const active = (people.data ?? []).filter((p) => !p.retired);
  const figures: Figures = {
    people: [...sofar.people, ...(people.data ?? []).map((p) => [p.name, ...p.aliases].map(nameKey))],
    due: [...sofar.due, ...(people.data ?? []).map(personDue)],
    overdue: [...sofar.overdue, ...(people.data ?? []).map((p) => overdueOf(p).total)],
    gradeDue: Object.fromEntries(
      // Every grade of the sheets so far and of this one: a grade a sheet lacks has no one on it there.
      [...new Set([...Object.keys(sofar.gradeDue), ...grades])].map((g) => [g, [...(sofar.gradeDue[g] ?? []), ...active.filter((p) => gradeOn(p.grades, today) === g).map(personDue)]]),
    ),
    statuses: Object.fromEntries(STATUSES.map((s) => [s, sofar.statuses[s] + statusCount(claims.data, s)])),
  };
  if (rest.length > 0) return <Consolidate sheets={rest} sofar={figures} />;
  return (
    <>
      People <strong data-testid="consolidated-people-count">{distinctPeople(figures.people)}</strong>{' '}
      Due total <strong data-testid="consolidated-due-total">{fig(trimmedTotal(figures.due))}</strong>{' '}
      Overdue total <strong data-testid="consolidated-overdue-total">{fig(trimmedTotal(figures.overdue))}</strong>
      {Object.keys(figures.gradeDue).map((g) => (
        <span key={g}>
          {' '}Grade {g} due total{' '}
          <strong data-testid={`consolidated-grade-${g}-due-total`}>{fig(dueTotal(figures.gradeDue[g]))}</strong>
        </span>
      ))}
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}{s} <strong data-testid={`consolidated-status-${s}-count`}>{figures.statuses[s]}</strong>
        </span>
      ))}
    </>
  );
}

// The consolidated figures over the sheet and all its descendants: their people, each counted once across the
// tree (people whose names or aliases match are one person); the due- and overdue-totals of every person of
// the tree added up, skipping n/a, trimmed once of the single highest and lowest when three or more have one; per grade, the due-totals of the people on it on their sheet's today
// (retired people left out) added up; and per status, how many claims have it. While the screen has an as-of date, every sheet of the tree is read
// as it stood at the end of that day, with that date as its today. A sheet with no children shows its own.
function ConsolidatedFigures() {
  const [sheet] = useCurrentSheet();
  const descendants = useDescendants(sheet);
  if (sheet === '' || !descendants.data) return null;
  return (
    <p data-testid="consolidated-figures">
      Consolidated{' '}
      <Consolidate key={descendants.data.join(',')} sheets={[sheet, ...descendants.data]} sofar={noFigures()} />
    </p>
  );
}

export const contribution = AppHeader.fill({ order: 31, Component: ConsolidatedFigures });
/** The sum of each figure (n/a counted as none) times its share ÷ 100, rounded half to even to two decimals. */
export function sharedTotal(parts: { figure: string; share: string }[]): string {
  // figure (hundredths) × share (hundredths) is in units of 1/10000 cent-percent: ÷ 10000 gives cents.
  const product = parts
    .filter((p) => p.figure !== NA)
    .reduce((sum, p) => sum + hundredths(p.figure) * hundredths(p.share), 0n);
  const abs = product < 0n ? -product : product;
  const rest = abs % 10000n;
  let cents = abs / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return format(product < 0n ? -cents : cents);
}

/** A sheet total of people's figures: their sum, skipping n/a, leaving out the single highest and the
 *  single lowest when three or more people have a figure. */
export function trimmedTotal(dues: string[]): string {
  const figures = dues.filter((d) => d !== NA).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return format(kept.reduce((sum, d) => sum + d, 0n));
}

/** What a claim's late charge follows: the sheet's late percent (two decimals) in force on a date and the
 *  30-day boundaries (yyyy-MM-dd) the claim is overdue past; and whether the claim's live figures round half up (else half to even);
 *  and the date (yyyy-MM-dd) its overdue is counted from: its due-by plus any grace days of its person's grade. */
export type Late = { pct: ((date: string) => string) | undefined; boundaries: (claim: Claim) => string[]; halfUp?: (claim: Claim) => boolean;
  graceBy?: (claim: Claim) => string };

/** The sheet's floor (two decimals) in force on a date; undefined for none known. */
export type Floor = ((date: string) => string) | undefined;

/** The late charge on a figure, compounding: for every full 30 days overdue, the late percent in force on that
 *  boundary of the figure plus the charges of the boundaries before it, rounded like due, added up (a boundary at
 *  0.00 adds nothing). None on a correction, nor on a claim whose charge was waived. */
function lateCharge(claim: Claim, figure: string, late: Late | undefined): string | undefined {
  const boundaries = late?.pct === undefined || isCorrection(claim) || claim.waived ? [] : late.boundaries(claim);
  if (boundaries.length === 0 || figure === NA) return undefined;

